import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M7 5H5c-.55 0-1-.45-1-1s.45-1 1-1h2V1c0-.55.45-1 1-1s1 .45 1 1v2h2c.55 0 1 .45 1 1s-.45 1-1 1H9v2c0 .55-.45 1-1 1s-1-.45-1-1zm7 9V8h-1V6h2.2a.8.8 0 0 1 .8.8v8.4a.8.8 0 0 1-.8.8H.8a.8.8 0 0 1-.8-.8V6.8A.8.8 0 0 1 .8 6H3v2H2v6z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M18 17V9h-2V7h3a1 1 0 0 1 1 1v10a1 1 0 0 1-1 1H1a1 1 0 0 1-1-1V8a1 1 0 0 1 1-1h3v2H2v8zM9 6H7c-.55 0-1-.45-1-1s.45-1 1-1h2V2c0-.55.45-1 1-1s1 .45 1 1v2h2c.55 0 1 .45 1 1s-.45 1-1 1h-2v2c0 .55-.45 1-1 1s-1-.45-1-1z"] as readonly string[];

export const AddParentIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="add-parent" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
AddParentIcon.displayName = `Blueprint6.Icon.AddParentIcon`;

/**
 * @deprecated Use {@link AddParentIcon} instead.
 */
export const AddParent: typeof AddParentIcon = AddParentIcon;

export default AddParentIcon;
